"use client";

import React from "react";

import {
  AlertDialog,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogFooter,
} from "@/components/ui/alert-dialog";
import { cn } from "@/lib/utils";

export interface AlertProps {
  open: boolean;
  onOpenChangeComplete?: ((open: boolean) => void) | undefined;
  onOpenChange: (open: boolean) => void;
  title?: string | undefined;
  description?: string | undefined;
  variant?: "default" | "destructive" | "success" | undefined;
  children?: React.ReactNode | undefined;
  body?: React.ReactNode | undefined;
}
const AlertRender = ({
  open,
  onOpenChange,
  onOpenChangeComplete,
  title = "Alert",
  description,
  variant = "default",
  children,
  body,
}: AlertProps) => (
  <AlertDialog
    open={open}
    onOpenChange={onOpenChange}
    onOpenChangeComplete={onOpenChangeComplete}
  >
    <AlertDialogContent
      className={cn(variant === "success" && "border-primary")}
    >
      <AlertDialogHeader>
        <AlertDialogTitle>{title}</AlertDialogTitle>
        {description && (
          <AlertDialogDescription>{description}</AlertDialogDescription>
        )}
      </AlertDialogHeader>
      {body}
      <AlertDialogFooter>{children}</AlertDialogFooter>
    </AlertDialogContent>
  </AlertDialog>
);
export const Alert = React.memo(AlertRender);
Alert.displayName = "Alert";

"use client";

import React, { useId, useState } from "react";

import {
  AlertDialogAction,
  AlertDialogCancel,
} from "@/components/ui/alert-dialog";
import { Input } from "@/components/ui/input";
import type { AlertProps } from "@/registry/new-york/ui-alert/Alert";
import { Alert } from "@/registry/new-york/ui-alert/Alert";

export interface ConfirmAlertProps extends Omit<
  AlertProps,
  "children" | "body"
> {
  confirmLabel?: string | undefined;
  cancelLabel?: string | undefined;
  onConfirm: () => void;
  /** Require this exact phrase before enabling confirmation. */
  confirmationText?: string | undefined;
}
const ConfirmAlertRender = ({
  open,
  onOpenChange,
  onOpenChangeComplete,
  title = "Confirm",
  description,
  variant = "default",
  confirmLabel = "Confirm",
  cancelLabel = "Cancel",
  onConfirm,
  confirmationText,
}: ConfirmAlertProps) => {
  const [phrase, setPhrase] = useState("");
  const inputId = useId();
  const canConfirm = !confirmationText || phrase === confirmationText;
  const handleConfirm = () => {
    if (canConfirm) {
      onConfirm();
    }
  };
  const handleOpenChangeComplete = (isOpen: boolean) => {
    if (!isOpen) {
      setPhrase("");
    }
    onOpenChangeComplete?.(isOpen);
  };
  return (
    <Alert
      open={open}
      onOpenChange={onOpenChange}
      onOpenChangeComplete={handleOpenChangeComplete}
      title={title}
      description={description}
      variant={variant}
      body={
        confirmationText ? (
          <div className="flex flex-col gap-2">
            <label htmlFor={inputId} className="text-sm">
              Type <strong>{confirmationText}</strong> to confirm
            </label>
            <Input
              id={inputId}
              value={phrase}
              onChange={(event) => setPhrase(event.target.value)}
              autoComplete="off"
              spellCheck={false}
            />
          </div>
        ) : undefined
      }
    >
      <AlertDialogCancel>{cancelLabel}</AlertDialogCancel>
      <AlertDialogAction
        disabled={!canConfirm}
        onClick={handleConfirm}
        className={
          variant === "destructive"
            ? "cursor-pointer bg-red-500/10 text-red-700 shadow-none hover:bg-red-500/20 dark:bg-red-400/10 dark:text-red-300 dark:hover:bg-red-400/20"
            : undefined
        }
      >
        {confirmLabel}
      </AlertDialogAction>
    </Alert>
  );
};
export const ConfirmAlert = React.memo(ConfirmAlertRender);
ConfirmAlert.displayName = "ConfirmAlert";

"use client";

import React from "react";

import type { ConfirmAlertProps } from "@/registry/new-york/ui-alert/ConfirmAlert";
import { ConfirmAlert } from "@/registry/new-york/ui-alert/ConfirmAlert";

export interface ConfirmAlertDeleteProps extends Omit<
  ConfirmAlertProps,
  "variant"
> {
  title?: string;
  itemName?: string;
}
const ConfirmAlertDeleteRender = ({
  open,
  onOpenChange,
  onOpenChangeComplete,
  title = "Confirm Delete",
  description,
  itemName,
  confirmLabel = "Delete",
  cancelLabel = "Cancel",
  onConfirm,
  confirmationText,
}: ConfirmAlertDeleteProps) => {
  const finalDescription =
    description ||
    `Are you sure you want to delete ${itemName ? `"${itemName}"` : "this item"}? This action cannot be undone.`;
  return (
    <ConfirmAlert
      open={open}
      onOpenChange={onOpenChange}
      onOpenChangeComplete={onOpenChangeComplete}
      title={title}
      description={finalDescription}
      variant="destructive"
      confirmLabel={confirmLabel}
      cancelLabel={cancelLabel}
      onConfirm={onConfirm}
      confirmationText={confirmationText}
    />
  );
};
export const ConfirmAlertDelete = React.memo(ConfirmAlertDeleteRender);
ConfirmAlertDelete.displayName = "ConfirmAlertDelete";

"use client";

import React, { useCallback, useContext, useMemo, useReducer } from "react";

import {
  alertReducer,
  generateId,
  initialState,
} from "@/registry/new-york/ui-alert/AlertContextState";
import { AlertContext } from "@/registry/new-york/ui-alert/AlertContextStore";
import type * as AlertContextTypesModule from "@/registry/new-york/ui-alert/AlertContextTypes";
import * as AlertRendererModule from "@/registry/new-york/ui-alert/AlertRenderer";
import type { ConfirmAlertProps } from "@/registry/new-york/ui-alert/ConfirmAlert";
import type { ConfirmAlertDeleteProps } from "@/registry/new-york/ui-alert/ConfirmAlertDelete";

export const { AlertRenderer } = AlertRendererModule;
export type AlertData = AlertContextTypesModule.AlertData;
export type AlertId = AlertContextTypesModule.AlertId;
export type AlertProviderProps = AlertContextTypesModule.AlertProviderProps;
export type AlertType = AlertContextTypesModule.AlertType;
export type BaseAlert = AlertContextTypesModule.BaseAlert;
export type ConfirmAlertData = AlertContextTypesModule.ConfirmAlertData;
export type DeleteAlertData = AlertContextTypesModule.DeleteAlertData;

export const AlertProvider: React.FC<AlertProviderProps> = ({ children }) => {
  const [state, dispatch] = useReducer(alertReducer, initialState);

  const handleOpenChange = useCallback((id: AlertId, open: boolean) => {
    dispatch({ payload: { id, open }, type: "SET_ALERT_OPEN" });
  }, []);
  const removeAlert = useCallback((id: AlertId) => {
    dispatch({ payload: { id }, type: "REMOVE_ALERT" });
  }, []);

  const confirmAlert = useCallback(
    (props: Omit<ConfirmAlertProps, "open" | "onOpenChange">) => {
      const id = generateId();
      dispatch({
        payload: { id, open: true, props, type: "confirm" },
        type: "ADD_ALERT",
      });
    },
    []
  );

  const confirmAlertDelete = useCallback(
    (props: Omit<ConfirmAlertDeleteProps, "open" | "onOpenChange">) => {
      const id = generateId();
      dispatch({
        payload: { id, open: true, props, type: "delete" },
        type: "ADD_ALERT",
      });
    },
    []
  );

  const value = useMemo(
    () => ({
      alerts: state.alerts,
      confirmAlert,
      confirmAlertDelete,
      handleOpenChange,
      removeAlert,
    }),
    [
      confirmAlert,
      confirmAlertDelete,
      handleOpenChange,
      removeAlert,
      state.alerts,
    ]
  );

  return (
    <AlertContext.Provider value={value}>
      {children}
      <AlertRenderer />
    </AlertContext.Provider>
  );
};

export const useAlerts = () => {
  const context = useContext(AlertContext);

  if (context === undefined) {
    throw new Error("useAlerts must be used within an AlertProvider");
  }

  return context;
};

export const useConfirmAlert = () => {
  const { confirmAlert } = useAlerts();
  return confirmAlert;
};

export const useConfirmAlertDelete = () => {
  const { confirmAlertDelete } = useAlerts();
  return confirmAlertDelete;
};

import type {
  AlertAction,
  AlertContextState,
} from "@/registry/new-york/ui-alert/AlertContextTypes";

export const initialState: AlertContextState = {
  alerts: [],
};
export const alertReducer = (
  state: AlertContextState,
  action: AlertAction
): AlertContextState => {
  switch (action.type) {
    case "ADD_ALERT": {
      return {
        ...state,
        alerts: [...state.alerts, action.payload],
      };
    }
    case "REMOVE_ALERT": {
      return {
        ...state,
        alerts: state.alerts.filter((alert) => alert.id !== action.payload.id),
      };
    }
    case "SET_ALERT_OPEN": {
      return {
        ...state,
        alerts: state.alerts.map((alert) =>
          alert.id === action.payload.id
            ? {
                ...alert,
                open: action.payload.open,
              }
            : alert
        ),
      };
    }
    default: {
      return state;
    }
  }
};
export const generateId = (): string => Math.random().toString(36).slice(2, 11);

"use client";

import { createContext } from "react";

import type { AlertContextValue } from "@/registry/new-york/ui-alert/AlertContextTypes";

export const AlertContext = createContext<AlertContextValue | undefined>(
  undefined
);

import type { ReactNode } from "react";

import type { ConfirmAlertProps } from "@/registry/new-york/ui-alert/ConfirmAlert";
import type { ConfirmAlertDeleteProps } from "@/registry/new-york/ui-alert/ConfirmAlertDelete";

export type AlertId = string;
export type AlertType = "confirm" | "delete";

export interface BaseAlert {
  id: AlertId;
  type: AlertType;
  open: boolean;
}

export interface ConfirmAlertData extends BaseAlert {
  type: "confirm";
  props: Omit<ConfirmAlertProps, "open" | "onOpenChange">;
}

export interface DeleteAlertData extends BaseAlert {
  type: "delete";
  props: Omit<ConfirmAlertDeleteProps, "open" | "onOpenChange">;
}

export type AlertData = ConfirmAlertData | DeleteAlertData;

export interface AlertContextState {
  alerts: AlertData[];
}

export type AlertAction =
  | { type: "ADD_ALERT"; payload: AlertData }
  | { type: "REMOVE_ALERT"; payload: { id: AlertId } }
  | { type: "SET_ALERT_OPEN"; payload: { id: AlertId; open: boolean } };

export interface AlertContextValue {
  alerts: AlertData[];
  confirmAlert: (
    props: Omit<ConfirmAlertProps, "open" | "onOpenChange">
  ) => void;
  confirmAlertDelete: (
    props: Omit<ConfirmAlertDeleteProps, "open" | "onOpenChange">
  ) => void;
  removeAlert: (id: AlertId) => void;
  handleOpenChange: (id: AlertId, open: boolean) => void;
}

export interface AlertProviderProps {
  children: ReactNode;
}

"use client";

import React, { useContext } from "react";

import { AlertContext } from "@/registry/new-york/ui-alert/AlertContextStore";
import { ConfirmAlert } from "@/registry/new-york/ui-alert/ConfirmAlert";
import { ConfirmAlertDelete } from "@/registry/new-york/ui-alert/ConfirmAlertDelete";

const AlertRendererComponent = () => {
  const context = useContext(AlertContext);
  if (!context) {
    return null;
  }
  const { alerts, handleOpenChange, removeAlert } = context;
  if (alerts.length === 0) {
    return null;
  }
  return (
    <>
      {alerts.map((alert) => {
        const onOpenChange = (open: boolean) =>
          handleOpenChange(alert.id, open);
        if (alert.type === "confirm") {
          const { props } = alert;
          return (
            <ConfirmAlert
              key={alert.id}
              open={alert.open}
              onOpenChange={onOpenChange}
              {...props}
              onOpenChangeComplete={(open) => {
                if (!open) {
                  removeAlert(alert.id);
                }
              }}
            />
          );
        }
        if (alert.type === "delete") {
          const { props } = alert;
          return (
            <ConfirmAlertDelete
              key={alert.id}
              open={alert.open}
              onOpenChange={onOpenChange}
              {...props}
              onOpenChangeComplete={(open) => {
                if (!open) {
                  removeAlert(alert.id);
                }
              }}
            />
          );
        }
        return null;
      })}
    </>
  );
};
export const AlertRenderer = React.memo(AlertRendererComponent);
AlertRenderer.displayName = "AlertRenderer";

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
